discrete ChargingManagementSystem
port:
    event input real CRS;  // We&#x27;ve received a request signal.
event input real SCS;  // Copy that.
event output real CCS; // Charging complete.
state:
    initial state Idle
        when entry() then
            statehold(0);
        end;
        when receive(CRS) then
            transition(ChargePreparation);
        end;
        when receive(SCS) then
            transition(Idle);
        end;
    end;

    state ChargePreparation
        when entry() then
            statehold(5);  // Assumptions of preparatory work5sec
end;
        when timeover() then
            transition(Charging);
        end;
        when receive(SCS) then
            transition(Idle);
        end;
    end;

    state Charging
        when entry() then
            statehold(0);
        end;
        when receive(SCS) then
            transition(Idle);
        end;
        when timeover() then
            transition(ChargeComplete);
        end;
    end;

    state ChargeComplete
        when entry() then
            statehold(300);  // 5Minute cooling time
end;
        when timeover() then
            transition(Idle);
            out
                send(CCS, 1);
        end;
    end;
end;
end;

discrete DischargeManagementSystem
port:
    event input real DRS;  // We&#x27;ve received a request for discharge.
event input real SDS;  // Copy that.
event output real DCS; // The discharge is complete.
state:
    initial state Idle
        when entry() then
            statehold(0);
        end;
        when receive(DRS) then
            transition(DischargePreparation);
        end;
        when receive(SDS) then
            transition(Idle);
        end;
    end;

    state DischargePreparation
        when entry() then
            statehold(5);  // Assumptions of preparatory work5sec
end;
        when timeover() then
            transition(Discharging);
        end;
        when receive(SDS) then
            transition(Idle);
        end;
    end;

    state Discharging
        when entry() then
            statehold(0);
        end;
        when receive(SDS) then
            transition(Idle);
        end;
        when timeover() then
            transition(DischargeComplete);
        end;
    end;

    state DischargeComplete
        when entry() then
            statehold(300);  // 5Minute cooling time
end;
        when timeover() then
            transition(Idle);
            out
                send(DCS, 1);
        end;
    end;
end;
end;

discrete MonitoringAndControlSystem
port:
    event input real ESS;  // Emergency shutdown signal.
event input real RS;   // Restart the signal.
event output real AHS; // Unusual processing signal
state:
    initial state NormalMonitoring
        when entry() then
            statehold(0);
        end;
        when detect(Anomaly) then
            transition(AnomalyHandling);
        end;
    end;

    state AnomalyHandling
        when entry() then
            statehold(0);
        end;
        when anomalyResolved() then
            transition(NormalMonitoring);
        end;
        when receive(ESS) then
            transition(Shutdown);
        end;
    end;

    state Shutdown
        when entry() then
            statehold(0);
        end;
        when receive(RS) then
            transition(NormalMonitoring);
        end;
    end;
end;
end;

